        *sq_N_e = ONE_BY_SQRT_N1920_SCAL;
        break;
    case 1440:
        *S = intDCT4_fx_N1440_S;
        *CS = intDCT4_fx_N1440_CS;
        *sq_N = ONE_BY_SQRT_N1440;
        *sq_N_e = ONE_BY_SQRT_N1440_SCAL;
