    #endif 
    case 960:
        *S = intDCT4_fx_N960_S;
        *CS = intDCT4_fx_N960_CS;
        *sq_N = ONE_BY_SQRT_N960;
        *sq_N_e = ONE_BY_SQRT_N960_SCAL;
        break;
