        *S = intDCT4_fx_N720_S;
        *CS = intDCT4_fx_N720_CS;
        *sq_N = ONE_BY_SQRT_N720;
        *sq_N_e = ONE_BY_SQRT_N720_SCAL;
        break;
    case 480:
        *S = intDCT4_fx_N480_S;
        *CS = intDCT4_fx_N480_CS;
        *sq_N = ONE_BY_SQRT_N480;
        *sq_N_e = ONE_BY_SQRT_N480_SCAL;
        break;
    case 360:
        *S = intDCT4_fx_N360_S;
        *CS = intDCT4_fx_N360_CS;
        *sq_N = ONE_BY_SQRT_N360;
        *sq_N_e = ONE_BY_SQRT_N360_SCAL;
        break;
    case 240:
        *S = intDCT4_fx_N240_S;
        *CS = intDCT4_fx_N240_CS;
        *sq_N = ONE_BY_SQRT_N240;
        *sq_N_e = ONE_BY_SQRT_N240_SCAL;
        break;
    case 120:
